2	// mirroring the binding input schema. Both operations read this vocabulary --
3	// quote reads cursed and enchantment for its risk surcharges, claim reads
4	// material and enchantment for its reimbursement clauses -- so it belongs to
5	// neither operation's policy module.
6	export interface Customer {
7	  yearsWithMHPCO: number;
8	}
