import type { Item } from "./insured-item.js";

export interface Damage {
  itemType: string;
  amount: number;
}

export interface Incident {
  cause: string;
  damages: Damage[];
}

export interface Policy {
  insuredItems: Item[];
}

export interface ClaimResult {
  payout: number;
}

const DEDUCTIBLE_PER_DAMAGE = 100;

// The MHPCO settles each damage event separately, withholding its deductible
// once per event. No reimbursement clause reduces the covered amount for the
// damages settled so far, so the full damage amount reaches the deductible.
function settlementForDamageEvent(damage: Damage): number {
  return damage.amount - DEDUCTIBLE_PER_DAMAGE;
}

export function claim(policy: Policy, incident: Incident): ClaimResult {
  const payout = incident.damages
    .map(settlementForDamageEvent)
    .reduce((sum, amount) => sum + amount, 0);
  return { payout };
}
